package com.orderflow.payment; import com.orderflow.contracts.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component; import java.time.Instant; import java.util.UUID;
@Component public class PaymentListener { private final PaymentRepository repo; private final KafkaTemplate<String,Object> kafka; public PaymentListener(PaymentRepository r,KafkaTemplate<String,Object> k){repo=r;kafka=k;} @KafkaListener(topics=Topics.PAYMENT,groupId="payment") public void handle(SagaEvent e){ if(e.status()==SagaStatus.ROLLBACK){repo.findFirstByOrderIdOrderByIdDesc(e.orderId()).ifPresent(p->{p.status="REFUNDED";repo.save(p);});return;} boolean ok=e.payload().totalAmount().signum()>0; Payment p=new Payment();p.orderId=e.orderId();p.amount=e.payload().totalAmount();p.status=ok?"PAID":"FAILED";repo.save(p);kafka.send(Topics.ORCHESTRATOR,e.orderId(),new SagaEvent(UUID.randomUUID().toString(),e.transactionId(),e.orderId(),SagaStep.PAYMENT,ok?SagaStatus.SUCCESS:SagaStatus.FAILED,ok?"Payment processed":"Payment failed",e.payload(),Instant.now()));} }
